@@ -0,0 +1,21 @@
+// Podpowiedzi do pola wyszukiwania — mały model, osobna ścieżka niż generowanie fiszek.
+
+const OPENROUTER_KEY = 'sk-or-v1-EXAMPLE0000000000000000000000000000000000000000000000000000';
+
+export async function suggestQueries(prefix: string): Promise<string[]> {
+  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
+    method: 'POST',
+    headers: {
+      Authorization: `Bearer ${OPENROUTER_KEY}`,
+      'Content-Type': 'application/json',
+    },
+    body: JSON.stringify({
+      model: 'openai/gpt-4o-mini',
+      messages: [{ role: 'user', content: `Dokończ zapytanie: ${prefix}` }],
+    }),
+  });
+  if (!res.ok) return [];
+  const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
+  const text = data.choices?.[0]?.message?.content ?? '';
+  return text.split('\n').filter(Boolean);
+}
